WITH parsed AS (SELECT id, customer_id, created_at, items, ship_to, attributes, ship_to.zip AS ship_zip, AGGREGATE(items, 0D, (acc, i) -> acc + i.qty * i.price, acc -> ROUND(acc, 2)) AS cart_value, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, ARRAY_CONTAINS(MAP_KEYS(attributes), 'utm_source') AS has_utm_source, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text FROM carts WHERE TO_DATE(created_at) < '2024-04-02') SELECT *, SUM(cart_value) OVER (PARTITION BY customer_id ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_cart_value, LEAD(cart_value, 2) OVER (PARTITION BY MONTH(created_at), customer_id ORDER BY cart_value, id) AS next_cart_value, NTILE(3) OVER (ORDER BY cart_value DESC, id) AS cart_value_bucket, COUNT(cart_value) OVER (PARTITION BY customer_id ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS cart_value_count_1h, SUM(cart_value) OVER (PARTITION BY TO_DATE(created_at), customer_id ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_cart_value_2 FROM parsed;
